use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::{Path,PathBuf},collections::{BTreeMap,BTreeSet},io::Read};
const R:&str="/home/ubuntu/src/zopro-perf-work/tripling-formation176";fn r(s:impl AsRef<Path>)->PathBuf{Path::new(R).join(s)}fn load(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}fn hash(p:impl AsRef<Path>)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0u8;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break;}h.update(&b[..n]);}format!("{:x}",h.finalize())}fn med(v:&[f64])->f64{let mut v=v.to_vec();v.sort_by(f64::total_cmp);v[v.len()/2]}fn close(a:f64,b:f64){assert!((a-b).abs()<=1e-12*a.abs().max(b.abs()).max(1.));}
fn main(){let a=load(r("analysis.json"));let pins=load(r("pins.json"));for(p,h)in pins.as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}let mut commands=0;for(dir,plan)in[("native","native-plan.json"),("runs","run-plan.json")]{assert_eq!(load(r(format!("{dir}/result.json")))["status"],"complete");for step in load(r(plan))["steps"].as_array().unwrap(){let n=step["name"].as_str().unwrap();let e=load(r(format!("{dir}/{n}/exit.json")));assert_eq!(e["success"],true);assert_eq!(e["returncode"],0);for stream in["stdout","stderr"]{assert_eq!(hash(r(format!("{dir}/{n}/{stream}.log"))),e[format!("{stream}_sha256")]);}commands+=1;}}assert_eq!(commands,315);let initial=load(r("native-initial/core-ON/exit.json"));assert_eq!(initial["success"],false);assert!(fs::read_to_string(r("native-initial/core-ON/stderr.log")).unwrap().contains("error[E0689]"));let before=fs::read_to_string(r("formation-initial.rs")).unwrap();assert_eq!(before.replacen("for p in[7,11,13,17,19,31]","for p in[7i64,11,13,17,19,31]",1),fs::read_to_string(r("formation.rs")).unwrap());let manifest=load("/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-30-g2-vector-sign-adoption176/artifacts/production-source-manifest.json");let audit=load(r("source-audit.json"));let mut exact=0;for(p,h)in manifest["source_files_sha256"].as_object().unwrap(){assert_eq!(hash(Path::new("/home/ubuntu/src/zk-tools/zopro").join(p)),h.as_str().unwrap());let q=r("source").join(p);if hash(&q)==h.as_str().unwrap(){exact+=1;continue;}let s=fs::read_to_string(q).unwrap();let suffix=match p.as_str(){"crates/zopro-core/src/lib.rs"=>audit["lib_suffix"].as_str().unwrap(),"crates/zopro-core/src/msm.rs"=>audit["msm_suffix"].as_str().unwrap(),_=>panic!("unexpectedsourceedit")};assert_eq!(format!("{:x}",Sha256::digest(s.strip_suffix(suffix).unwrap().as_bytes())),h.as_str().unwrap());}assert_eq!(exact,174);let tests=load(r("native/core-ON/tests.json"));assert_eq!(tests["passed_tests"].as_array().unwrap().len(),128);assert_eq!(tests["unfiltered"],true);let oracle=fs::read_to_string(r("native/ark-oracles/stdout.log")).unwrap();assert!(oracle.starts_with("ARK_ORACLE_PASS G1=3712 G2=3712"));
 let jobs=load(r("jobs.json"));let mut cells=BTreeMap::<String,Vec<(usize,f64)>>::new();let mut measured=0u64;let mut primes=0u64;let mut points=0u64;let mut profile_samples=0;let mut qualified=0;for j in jobs.as_array().unwrap(){let name=j["name"].as_str().unwrap();let s=fs::read_to_string(r(format!("runs/{name}/stdout.log"))).unwrap();let lines=s.lines().filter(|l|l.starts_with("RESULT ")).collect::<Vec<_>>();assert_eq!(lines.len(),1);let v:Value=serde_json::from_str(lines[0].strip_prefix("RESULT ").unwrap()).unwrap();assert_eq!(v["timed_allocations"],0);assert_eq!(v["internally_verified"],true);assert_eq!(v["iterations_per_worker"],j["rounds"]);let workers=v["workers"].as_array().unwrap();let sum=workers.iter().map(|w|w["elapsed_ns"].as_u64().unwrap()as u128).sum::<u128>();let size=v["size"].as_u64().unwrap();let iterations=v["iterations_per_worker"].as_u64().unwrap();let count=iterations*workers.len()as u64;let ns=sum as f64/(count*size)as f64;let wc=workers.iter().map(|w|w["cpu"].as_u64().unwrap()).collect::<BTreeSet<_>>();assert_eq!(wc.len(),workers.len());for w in workers{assert_eq!(w["digest"],v["output_sha256"]);assert_eq!(w["capacity_bytes"],v["capacity_bytes_per_worker"]);assert_eq!(w["reference_bytes"],v["fixture_reference_bytes_per_worker"]);}measured+=count;primes+=3*v["prime_iterations_per_worker"].as_u64().unwrap()*workers.len()as u64;points+=count*size;if j["phase"]=="latency"{cells.entry(j["context"]["name"].as_str().unwrap().into()).or_default().push((j["block"].as_u64().unwrap()as usize,ns));}if j["phase"]=="profile"{let text=fs::read_to_string(r(format!("runs/decode-{name}/stdout.log"))).unwrap();let mut n=0;let mut unknown=0;let tids=workers.iter().map(|w|w["tid"].as_i64().unwrap()).collect::<BTreeSet<_>>();let mut pids=BTreeSet::new();for line in text.lines().filter(|l|!l.trim().is_empty()&&!l.trim().starts_with('#')){let f=line.split_whitespace().collect::<Vec<_>>();let(pp,tt)=f[0].split_once('/').unwrap();let pp=pp.parse::<i64>().unwrap();let tt=tt.parse::<i64>().unwrap();pids.insert(pp);assert!(tids.contains(&tt)||pp==tt);assert!(wc.contains(&f[1].trim_matches(['[',']']).parse::<u64>().unwrap()));assert_eq!(f[2],"16000000");unknown+=usize::from(f[4..].join(" ").contains("unknown"));n+=1;}assert_eq!(pids.len(),1);assert_eq!(a["profiles"][name]["samples"],n);let q=n>=1000&&(unknown as f64/n as f64)<=0.05;assert_eq!(a["profiles"][name]["qualified"],q);assert_eq!(a["profiles"][name]["zero_lost"],true);qualified+=usize::from(q);profile_samples+=n;}}
 assert_eq!(measured,a["measured_kernel_calls"]);assert_eq!(primes,a["prime_kernel_calls"]);assert_eq!(points,a["measured_point_calls"]);for(k,v)in&mut cells{v.sort_by_key(|x|x.0);assert_eq!(v.len(),15);assert!(v.iter().enumerate().all(|(i,x)|i==x.0));close(med(&v.iter().map(|v|v.1).collect::<Vec<_>>()),a["cells"][k]["median_ns_per_point"].as_f64().unwrap());}let mut failed=Vec::new();for curve in["g1","g2"]{let budget=if curve=="g1"{24997f64/18626.}else{50652f64/27919.};for topo in["solo","physical16","logical32"]{for reference in[200,352]{let key=format!("{curve}/{topo}/triple1024/add{reference}");let ratios=(0..15).map(|i|cells[&format!("{curve}-1024-{topo}")][i].1/cells[&format!("{curve}-{reference}-{topo}")][i].1).collect::<Vec<_>>();for(i,v)in ratios.iter().enumerate(){close(*v,a["pairs"][&key]["ratios"][i].as_f64().unwrap());}let mut sorted=ratios;sorted.sort_by(f64::total_cmp);for(name,idx)in[("median",7),("low",3),("high",11)]{close(sorted[idx],a["pairs"][&key][name].as_f64().unwrap());}let pass=sorted[11]<budget;assert_eq!(a["pairs"][&key]["budget_upper_passed"],pass);if topo!="solo"{assert_eq!(a["checks"][&key],pass);if !pass{failed.push(key);}}}}}failed.sort();assert_eq!(json!(failed),a["failed_checks"]);assert_eq!(failed.len(),8);assert_eq!(a["formation_budget_screen_passed"],false);assert_eq!(a["proof_ledger"],29461);let review=json!({"passed":true,"pin_entries":pins.as_object().unwrap().len(),"successful_commands":commands,"retained_initial_compile_failure":"E0689 toyprime type, no test executed; onlyi64annotation changed","native_core_unfiltered_tests":128,"Ark_G1":3712,"Ark_G2":3712,"originals_exact":174,"originals_recovered":176,"all_raw_worker_integer_ns_and_budget_gates_reconstructed":true,"processes":292,"profile_samples":profile_samples,"profiles_qualified":qualified,"profiles_below1000_retained":4-qualified,"all_profiles_zero_LOST_and_own_PID_CPU":true,"measured_kernel_calls":measured,"prime_kernel_calls":primes,"formation_budget_screen_passed":false,"failed_checks":failed,"new_proofs":0,"proof_ledger":29461,"adopted":false,"production_changed":false});save(r("review.json"),&review);println!("{review}");}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
